def do_ranges_overlap(start1: int, end1: int, start2: int, end2: int) -> bool:
    """Buggy: uses strict overlap logic (touching endpoints treated as non-overlap)."""
    if start1 > end1:
        raise ValueError("Invalid range1: start1 must be <= end1")
    if start2 > end2:
        raise ValueError("Invalid range2: start2 must be <= end2")

    # Incorrect for inclusive ranges: treats boundary touch as non-overlap.
    return not (end1 <= start2 or end2 <= start1)

def do_ranges_overlap(start1: int, end1: int, start2: int, end2: int) -> bool:
    """Buggy: only checks whether range2's endpoints fall inside range1."""
    if start1 > end1:
        raise ValueError("Invalid range1: start1 must be <= end1")
    if start2 > end2:
        raise ValueError("Invalid range2: start2 must be <= end2")

    # Fails when range2 is fully inside range1 but neither endpoint check matches due to wrong direction,
    # and also fails when range1 is fully inside range2.
    return (start1 <= start2 <= end1) or (start1 <= end2 <= end1)

def do_ranges_overlap(start1: int, end1: int, start2: int, end2: int) -> bool:
    """Buggy: wrong boolean operator when checking separation."""
    if start1 > end1:
        raise ValueError("Invalid range1: start1 must be <= end1")
    if start2 > end2:
        raise ValueError("Invalid range2: start2 must be <= end2")

    # Should be: not (end1 < start2 or end2 < start1)
    # Bug: uses 'and', making many disjoint ranges look overlapping.
    return not (end1 < start2 and end2 < start1)

def do_ranges_overlap(start1: int, end1: int, start2: int, end2: int) -> bool:
    """Buggy: silently normalizes invalid ranges instead of raising ValueError."""
    a1, b1 = (start1, end1) if start1 <= end1 else (end1, start1)
    a2, b2 = (start2, end2) if start2 <= end2 else (end2, start2)

    return not (b1 < a2 or b2 < a1)
